<script setup>
import {ref,computed,onMounted,watch,nextTick} from 'vue'
import {api,boot,session,fmt,money,localTime,roleNames,statusTone,businessName} from './api'
import DataTable from './components/DataTable.vue'
import IntegrityPanel from './components/IntegrityPanel.vue'
import AppIcon from './components/AppIcon.vue'
import FormDialog from './components/FormDialog.vue'
import PublicPortal from './components/PublicPortal.vue'
import KnowledgeList from './components/KnowledgeList.vue'
import LoginDialog from './components/LoginDialog.vue'
import {createDetailLoader} from './detail-loader'
import {dispatchTargets} from './dispatch-targets'
import {articleArt} from './article-art'
import {articleCategories,articleCategory} from './article-categories'
const page=ref(location.hash.slice(1)||'dashboard'),busy=ref(false),error=ref(''),toast=ref(''),rows=ref([]),stats=ref({metrics:[],daily:[],risks:[]}),meta=ref({}),modal=ref(null),detail=ref(null),mobile=ref(false),receiptResult=ref(null),loginBusy=ref(false)
const visitAttention=ref([])
const username=ref(''),password=ref(''),from=ref(''),to=ref(''),queryCode=ref(''),queryToken=ref(''),queryResult=ref(null)
const loginOpen=ref(false),loginTarget=ref('dashboard'),loginRole=ref('PUBLIC'),loginError=ref(''),queryBusy=ref(false)
const user=computed(()=>session.user),role=computed(()=>user.value?.role||'GUEST'),isCenter=computed(()=>role.value==='CENTER'),isAdmin=computed(()=>user.value?.admin)
const navigation=[{id:'dashboard',label:'协同总览',roles:['CENTER','PAYMENT','GRID','PUBLIC']},{id:'reports',label:'举报与线索',roles:['PUBLIC','CENTER']},{id:'alerts',label:'研判与复核',roles:['CENTER']},{id:'commands',label:'协同指令',roles:['CENTER','PAYMENT','PUBLIC']},{id:'visits',label:'上门劝阻',roles:['CENTER','GRID']},{id:'applications',label:'返还与申诉',roles:['CENTER','PUBLIC']},{id:'notices',label:'时效与督办',roles:['CENTER']},{id:'campaigns',label:'社区宣防',roles:['CENTER','GRID']},{id:'articles',label:'反诈知识',roles:['CENTER','PUBLIC','GRID','PAYMENT']},{id:'banks',label:'资金账户',roles:['PAYMENT','CENTER','PUBLIC']},{id:'people',label:'实名人员',roles:['CENTER'],admin:true},{id:'corrections',label:'回执更正',roles:['PAYMENT','CENTER']},{id:'blacklist',label:'风险名单',roles:['CENTER']},{id:'configs',label:'规则配置',roles:['CENTER']},{id:'users',label:'账号管理',roles:['CENTER'],admin:true},{id:'logs',label:'操作日志',roles:['CENTER']}]
const menus=computed(()=>navigation.filter(n=>n.roles.includes(role.value)&&(!n.admin||isAdmin.value)))
const navIcons={dashboard:'dashboard',reports:'file',alerts:'alert',commands:'exchange',visits:'pin',applications:'application',notices:'clock',campaigns:'campaign',articles:'book',banks:'bank',people:'users',corrections:'history',blacklist:'list',configs:'settings',users:'users',logs:'file',lookup:'search'}
const quickLinks=computed(()=>({PUBLIC:[{id:'reports',label:'举报与线索',hint:'查看已提交线索与受理进度'},{id:'applications',label:'返还与申诉',hint:'办理资金返还与误冻结申诉'},{id:'articles',label:'反诈知识',hint:'了解常见骗局与防范方法'}],PAYMENT:[{id:'commands',label:'协同指令',hint:'受理指令并提交执行回执'},{id:'banks',label:'账户管理',hint:'核对账户信息及可用余额'},{id:'corrections',label:'回执更正',hint:'申请更正并跟踪审核结果'}],GRID:[{id:'visits',label:'上门劝阻',hint:'接收任务、记录到场及回传'},{id:'campaigns',label:'社区宣防',hint:'查看宣传任务并记录活动'},{id:'articles',label:'反诈知识',hint:'查阅宣传与劝阻参考内容'}]}[role.value]||[]))
const navGroups=computed(()=>{
 const available=user.value?menus.value:[{id:'articles',label:'反诈知识'},{id:'lookup',label:'举报查询'}]
 const work=['dashboard','reports','alerts','commands','visits','applications','notices','banks']
 return [{label:'业务工作台',items:available.filter(m=>work.includes(m.id))},{label:user.value?'协作与管理':'公共服务',items:available.filter(m=>!work.includes(m.id))}].filter(g=>g.items.length)
})
const title=computed(()=>({dashboard:role.value==='PUBLIC'?'我的服务台':role.value==='GRID'?'社区协同工作台':role.value==='PAYMENT'?'机构处置工作台':'协同处置总览',reports:role.value==='PUBLIC'?'我的举报':'举报与线索',anonymous:'匿名举报',lookup:'举报进度查询',welcome:'欢迎使用',...Object.fromEntries(navigation.filter(n=>n.id!=='dashboard'&&n.id!=='reports').map(n=>[n.id,n.label]))}[page.value]||'反诈协同处置平台'))
const columns=computed(()=>({
 reports:[{key:'code',label:'受理编号'},{key:'kind',label:'类型'},{key:'source',label:'来源',format:businessName},{key:'processing',label:'研判状态',badge:true},{key:'state',label:'办理状态',badge:true},{key:'created_at',label:'受理时间'}],
 alerts:[{key:'code',label:'预警编号'},{key:'level',label:'风险等级',badge:true},{key:'score',label:'评分'},{key:'clue_count',label:'关联线索'},{key:'community_name',label:'所属社区'},{key:'state',label:'状态',badge:true},{key:'needs_review',label:'补充复核'}],
 commands:[...(role.value==='PUBLIC'?[{key:'relationship',label:'与我的关系'}]:[]),{key:'code',label:'指令编号'},{key:'kind',label:'类型'},{key:'account',label:'账户'},{key:'requested',label:'指令金额',format:v=>v==null?'待机构核定':money(v)},{key:'actual',label:'实际执行',format:money},{key:'state',label:'状态',badge:true},{key:'expires_at',label:'到期时间'}],
 visits:[{key:'code',label:'任务编号'},{key:'level',label:'风险',badge:true},{key:'community_name',label:'社区'},{key:'assignee',label:'执行人'},{key:'state',label:'状态',badge:true},{key:'due_at',label:'要求完成时间'}],
 applications:[{key:'code',label:'申请编号'},{key:'kind',label:'申请类型'},{key:'original_code',label:'原止付'},{key:'amount',label:'申请金额',format:v=>v==null?'—':money(v)},{key:'approved',label:'核定金额',format:(v,r)=>r.kind!=='返还'||v==null?'—':money(v)},{key:'credited',label:'实际入账',format:v=>v==null?'—':money(v)},{key:'state',label:'申请状态',badge:true},{key:'progress_state',label:'办理进度',badge:true}],
 notices:[{key:'code',label:'关联指令'},{key:'node',label:'提醒节点',badge:true},{key:'message',label:'提醒内容',wide:true},{key:'resolved',label:'已处理'},{key:'created_at',label:'提醒时间'}],
 campaigns:[{key:'title',label:'宣传任务',wide:true},{key:'community_name',label:'社区'},{key:'sessions',label:'已开展场次'},{key:'people',label:'触达人次'},{key:'due_at',label:'截止时间'},{key:'state',label:'状态',badge:true}],
 people:[{key:'name',label:'姓名'},{key:'phone',label:'联系电话'},{key:'identity',label:'证件信息'},{key:'community_name',label:'社区'}],
 banks:[{key:'owner_person_id',label:'户主核验',format:v=>v?'已核验':'待核验'},{key:'account',label:'账户'},{key:'holder',label:'户名',format:businessName},{key:'org_name',label:'机构',format:businessName},{key:'available',label:'可用余额',format:money}],
 corrections:[{key:'code',label:'原指令'},{key:'reason',label:'更正原因',wide:true},{key:'new_result',label:'申请结果'},{key:'new_amount',label:'申请金额',format:money},{key:'state',label:'审核状态',badge:true}],
 blacklist:[{key:'kind',label:'类型'},{key:'value',label:'匹配内容',wide:true},{key:'source',label:'来源依据',wide:true},{key:'enabled',label:'启用'}],
 users:[{key:'username',label:'账号'},{key:'display_name',label:'显示名称',format:businessName},{key:'role',label:'角色',format:v=>roleNames[v]},{key:'enabled',label:'启用'},{key:'verified',label:'身份关联'},{key:'admin',label:'管理权限'}],
 logs:[{key:'created_at',label:'时间'},{key:'actor',label:'操作人'},{key:'actor_role',label:'操作时角色',format:v=>roleNames[v]||v||'历史记录'},{key:'action',label:'动作'},{key:'entity_type',label:'对象'},{key:'new_state',label:'结果'},{key:'note',label:'说明',wide:true}]
}[page.value]||[]))
const detailLoader=createDetailLoader({request:api,start:(type,row)=>{error.value='';detail.value={type,id:row.id,data:row,loading:true}},commit:value=>{detail.value=value},fail:e=>{if(detail.value)detail.value={...detail.value,loading:false};error.value=e.message}})
function closeDetail(){detailLoader.invalidate();detail.value=null;error.value=''}
const retryingReport=ref(false)
const accountMenu=ref(null)
watch(()=>user.value?.id,()=>closeDetail(),{flush:'sync'})
function go(id){if(accountMenu.value)accountMenu.value.open=false;location.hash=id;page.value=id;closeDetail();error.value='';mobile.value=false;nextTick(()=>window.scrollTo({top:0,behavior:'instant'}))}
window.addEventListener('hashchange',()=>{page.value=location.hash.slice(1)||'dashboard';closeDetail();mobile.value=false})
function notify(text){toast.value=text;setTimeout(()=>toast.value='',5000)}
let refreshSequence=0
function clearView(){refreshSequence++;rows.value=[];visitAttention.value=[];stats.value={metrics:[],daily:[],risks:[]};meta.value={};pagination.value=null;closeDetail();modal.value=null;receiptResult.value=null;error.value=''}
async function refresh(){
 if(!session.ready)return;
 if(!user.value){
  if(!['welcome','articles','lookup'].includes(page.value)){go('welcome');return}
  const sequence=++refreshSequence;busy.value=true;error.value=''
  try{if(page.value!=='lookup'){const articles=await api('/articles');if(sequence===refreshSequence)rows.value=articles}}
  catch(e){if(sequence===refreshSequence)error.value=e.message}finally{if(sequence===refreshSequence)busy.value=false}
  return
 }
 if(!menus.value.some(m=>m.id===page.value)){page.value='dashboard';return}
 const sequence=++refreshSequence,currentPage=page.value,currentRole=role.value;
 busy.value=true;error.value='';
 try{
  const nextMeta=await api('/meta');let nextRows,nextStats,nextPagination=null;const nextAttention=currentPage==='notices'?await api('/visit-attention'):[];
  if(currentPage==='dashboard'){
   nextStats=await api('/stats?'+new URLSearchParams({from:from.value,to:to.value}));
   const endpoint=currentRole==='CENTER'?'/alerts':currentRole==='GRID'?'/visits':currentRole==='PAYMENT'?'/commands':'/reports';nextRows=await api(endpoint)
  }else if(pagedResources.has(currentPage)){
   nextPagination=await api('/list/'+currentPage+'?'+new URLSearchParams(listQuery.value));nextRows=nextPagination.items
  }else nextRows=await api('/'+currentPage);
  if(sequence!==refreshSequence)return;
  visitAttention.value=nextAttention;meta.value=nextMeta;rows.value=nextRows;pagination.value=nextPagination;if(nextStats)stats.value=nextStats;
  if(detail.value)await openDetail(detail.value.type,['notices','blacklist','banks'].includes(detail.value.type)?rows.value.find(x=>x.id===detail.value.id)||detail.value.data:{id:detail.value.id})
 }catch(e){if(sequence===refreshSequence)error.value=e.message}finally{if(sequence===refreshSequence)busy.value=false}
}
watch(page,()=>{closeDetail();rows.value=[];listQuery.value={page:1,q:'',state:''};pagination.value=null;nextTick(()=>window.scrollTo({top:0,behavior:'instant'}));refresh()})
onMounted(async()=>{try{await boot();await refresh()}catch(e){error.value=e.message;session.ready=true}})
function openLogin(target='dashboard'){loginError.value='';loginTarget.value=target;if(target==='applications')loginRole.value='PUBLIC';loginOpen.value=true}
watch(loginRole,()=>{loginError.value=''})
async function login(){loginBusy.value=true;loginError.value='';try{const r=await api('/login',{username:username.value,password:password.value,role:loginRole.value});clearView();session.user=r.user;password.value='';loginOpen.value=false;go(menus.value.some(m=>m.id===loginTarget.value)?loginTarget.value:'dashboard');await refresh()}catch(e){loginError.value=e.message}finally{loginBusy.value=false}}
async function logout(){closeDetail();try{await api('/logout',{});clearView();session.user=null;await boot();go('welcome')}catch(e){error.value=e.message}}
function demo(name){username.value=name;password.value='Demo2026!'}
async function query(){error.value='';queryResult.value=null;queryBusy.value=true;try{queryResult.value=await api('/anonymous/query',{code:queryCode.value,token:queryToken.value})}catch(e){error.value=e.message}finally{queryBusy.value=false}}
watch([detail,modal,receiptResult,loginOpen],()=>{document.body.classList.toggle('overlay-open',!!(detail.value||modal.value||receiptResult.value||loginOpen.value))})
watch(detail,async(value,previous)=>{if(value&&(value.id!==previous?.id||value.type!==previous?.type)){await nextTick();document.querySelector('.drawer-body')?.scrollTo({top:0});document.querySelector('.detail-drawer')?.focus({preventScroll:true})}})
window.addEventListener('keydown',event=>{if(!detail.value||modal.value)return; if(event.key==='Escape'){closeDetail();return}if(event.key==='Tab'){const items=[...document.querySelectorAll('.detail-drawer button:not(:disabled),.detail-drawer a,.detail-drawer input,.detail-drawer select')].filter(x=>x.offsetParent!==null);const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}})
const exportUrl=computed(()=>'/api/stats.csv?'+new URLSearchParams({from:from.value,to:to.value}))
const pagination=ref(null),listQuery=ref({page:1,q:'',state:''})
const pagedResources=new Set(['reports','alerts','commands','visits','applications','notices','campaigns','banks','corrections','blacklist','users','logs'])
function listChanged(q){listQuery.value=q;refresh()}
const option=(values,key='id',label='name')=>(values||[]).map(v=>({value:v[key],label:businessName(v[label])}))
const f=(key,label,type='text',extra={})=>({key,label,type,...extra})
const note=(label='处理意见',max=1000)=>f('note',label,'textarea',{required:true,max})
const attachment=(required=false)=>f('attachments','证明或过程材料','file',{required})
function form(title,fields,path,initial={},description='',transform=x=>x,summary=null){modal.value={title,fields,initial,description,summary,submit:async data=>api(path,transform(data))}}
async function done(result){modal.value=null;notify('已保存，办理记录已更新。');if(result?.queryToken){receiptResult.value=result}else await refresh()}
async function openDetail(type,row){
 if(type==='banks'){if(isAdmin.value)bankForm(row);return}
 if(type==='people')return
 if(type==='users'){closeDetail();editUser(row);return}
 if(type==='blacklist'&&isAdmin.value){closeDetail();editBlacklist(row);return}
 await detailLoader.open(type,row)
}
async function retryReport(report){
 if(retryingReport.value)return
 const version=detailLoader.version();retryingReport.value=true;error.value=''
 try{await api(`/reports/${report.id}/retry`,{});if(version!==detailLoader.version())return;notify('原举报已重新研判，可继续办理。');await refresh()}
 catch(e){if(version===detailLoader.version())error.value='重新研判未完成：'+e.message+'。原举报已保留，可稍后重试。'}
 finally{retryingReport.value=false}
}
function select(row){openDetail(page.value,row)}
async function action(path,b={}){error.value='';try{await api(path,b);notify('操作成功，状态已更新。');await refresh()}catch(e){error.value=e.message}}
function reportForm(){
 form(isCenter.value?'录入监测线索':'提交举报线索',[
  f('kind','线索类型','select',{section:'线索信息',options:['号码','账户','网址'],required:true}),
  f('value','号码、账户或网址','text',{required:true,placeholder:'填写需要核查的线索'}),
  f('reporterRelation','我与事件的关系','select',{wide:true,required:true,options:['本人受损','代他人举报','提供线索'],help:'举报中的账户、号码或网址是待核查线索，并非举报人自己的收款账户。'}),
  f('description','情况说明','textarea',{required:true,rows:3,placeholder:'描述事情经过、联系渠道及需要核查的情况。'}),
  f('amount','涉及交易金额','number',{section:'交易情况',min:0,step:'.01',unit:'元',optional:true,placeholder:'请输入金额'}),
  f('transactionTime','交易时刻','time',{optional:true}),
  f('remote','异地交易','checkbox'),f('repeat','短时重复交易','checkbox'),f('newLarge','新开户大额交易','checkbox'),
  {...attachment(),section:'材料与提交'},
  ...(isCenter.value?[f('victimId','已核验受害人','select',{wide:true,options:option(meta.value.victims),help:'未确认主体时可留空，后续由中心补录。'})]:user.value?.verified?[f('anonymous','匿名提交','checkbox',{wide:true,help:'提交后请保存受理编号和查询凭证，用于查询办理进度。'})]:[])
 ],'/reports',{kind:'号码',reporterRelation:'提供线索',anonymous:!isCenter.value&&!user.value?.verified,requestKey:crypto.randomUUID()},'请填写已知信息；不确定的交易情况可以留空。')
}
function reviewForm(a){form('人工复核',[f('decision','复核结论','select',{options:['通过','驳回'],required:true}),f('level','确认风险等级','select',{options:['高','中','低'],required:true}),f('victimId','核验后的受害人','select',{options:option(meta.value.victims)}),f('communityId','派发社区','select',{options:option(meta.value.communities)}),note()],`/alerts/${a.id}/review`,{decision:'通过',level:a.level,victimId:a.victim_id||'',communityId:a.community_id||''},'派发前更正受害人会同步更新关联举报并保留日志；派发后不能修改归属。')}
function dispatchForm(a){form('联动派发',[f('bankId','目标账户','select',{required:true,wide:true,options:dispatchTargets((meta.value.banks||[]).filter(b=>(a.targets||[]).some(t=>t.bank_id===b.id)),a.commands).map(b=>({value:b.id,label:businessName(b.org_name)+' · '+b.account+' · '+businessName(b.holder)+' · '+b.dispatchLabel,disabled:b.disabled})),help:'失败账户请从预警的关联指令进入“复核重发”。'}),f('amount','申请止付金额','number',{min:.01,step:.01,help:'新派发时填写，可留空由机构核查；复用保留原指令金额。'})],`/alerts/${a.id}/dispatch`,{},'未派发过的账户可新建止付；进行中的指令复用原单号，上门任务保持不变。')}
function linkAccountForm(a,candidate={}){form('核验线索关联账户',[f('reportId','依据的举报线索','select',{required:true,wide:true,options:(a.reports||[]).map(r=>({value:r.id,label:r.code+' · '+r.kind+' · '+r.value}))}),f('bankId','已查明的资金账户','select',{required:true,wide:true,options:(meta.value.banks||[]).map(b=>({value:b.id,label:b.account+' · '+businessName(b.holder)+' · '+businessName(b.org_name)}))}),note('核验依据与材料位置')],`/alerts/${a.id}/accounts`,{reportId:candidate.report_id||a.reports?.[0]?.id||'',bankId:candidate.id||''},'号码、网址不能直接推出银行账户。请根据交易凭证、机构核查或既有证据确认关系；保存后需再次人工复核。')}
function personForm(){form('新增已核验人员',[f('name','姓名','text',{required:true}),f('identity','证件标识','text',{required:true}),f('phone','联系电话','text',{required:true}),f('communityId','所属社区','select',{required:true,options:option(meta.value.communities)}),note('身份核验依据')],'/people')}
function bankForm(a={}){
 if(a.id&&a.owner_person_id){closeDetail();void detailLoader.open('banks',a);return}
 form(a.id?'核验账户户主':'登记资金账户',[
 ...(a.id?[]:[f('number','资金账号','text',{required:true}),f('orgId','所属机构','select',{required:true,options:option(meta.value.orgs)}),f('opening','期初可用余额','number',{required:true,min:0,step:.01})]),
 f('personId','已核验实名户主','select',{required:true,options:option(meta.value.victims)}),note('账户权属核验依据')],a.id?`/banks/${a.id}/owner`:'/banks',{personId:a.owner_person_id||'',opening:0},a.id?'账户 '+a.account+'；已核验账户不能更换为另一户主。':'群众可以有多个本人账户，也可以暂不绑定；返还必须选择本人收款账户，申诉必须为被冻结账户户主。')}
function receiptForm(c){form('提交'+c.kind+'回执',[f('result','核查结果','select',{required:true,options:c.kind==='解除'?['解除成功','拒绝执行']:['全额执行','部分执行','拒绝执行']}),...(c.kind==='解除'?[]:[f('amount','实际执行金额','number',{min:0,step:.01,required:true})]),f('reason','执行说明或原因','textarea',{max:1000,help:c.kind==='解除'?'拒绝解除时必须填写原因。':'部分执行与拒绝执行必须填写原因；拒绝时金额为0。'}),f('voucher','凭证编号','text',{required:true}),attachment()],`/commands/${c.id}/receipt`,{result:c.kind==='解除'?'解除成功':'全额执行',amount:c.kind==='解除'?0:c.requested??'',voucher:'RCP-'+Date.now()},'提交后更新指令执行结果与账户余额。')}
function fundSummary(c){return c?[{label:'剩余冻结',value:money(c.remaining)},{label:'待执行占用',value:money(c.reserved)},{label:'当前可核定',value:money(Number(c.remaining)-Number(c.reserved))}]:[]}
async function applicationForm(kind){
 const version=detailLoader.version()
 try{const commands=await api('/commands');if(version!==detailLoader.version())return;const eligible=commands.filter(c=>kind==='返还'?c.refund_eligible:c.appeal_eligible);if(!eligible.length){notify(kind==='返还'?'没有中心确认您为受害人的有效止付。':'您的已核验资金账户目前没有可申诉的冻结。');return}
 const ownBanks=await api('/banks');if(version!==detailLoader.version())return;if(kind==='返还'&&!ownBanks.length){notify('请先由中心核验登记您的本人收款账户，可在资金账户页面查看。');return}
 form('提交'+kind+'申请',[f('originalId',kind==='返还'?'受害人关联止付':'本人账户冻结记录','select',{required:true,options:eligible.map(c=>({value:c.id,label:c.code+' · '+c.account}))}),...(kind==='返还'?[f('amount','申请金额','number',{min:.01,step:.01,required:true}),f('payeeBankId','本人收款账户','select',{required:true,options:ownBanks.map(b=>({value:b.id,label:b.account+' · '+businessName(b.holder)})),help:'只可选择经核验归属于本人的账户，不能是原被止付账户。'})]:[]),f('reason','申请理由','textarea',{required:true}),attachment(kind==='返还')],'/applications',{kind,originalId:eligible[0].id},kind==='返还'?'可核定金额为剩余冻结减去待执行占用，最终以中心核定时的余额为准。':'仅限被冻结资金账户的户主申诉；举报人或受害人身份不会自动取得该权利。',x=>x,data=>{const c=eligible.find(c=>String(c.id)===String(data.originalId));return kind==='返还'?fundSummary(c):c?[{label:'本人账户剩余冻结',value:money(c.remaining)}]:[]})
 }catch(e){if(version===detailLoader.version())error.value=e.message}
}
function applicationReview(a,decision){form(a.kind==='返还'?'核定返还申请':'处理申诉',[f('decision','处理结论','select',{required:true,options:a.kind==='返还'?['通过','驳回']:a.state==='待受理'?['受理']:['补正','维持','成立']}),...(a.kind==='返还'?[f('amount','本次核定金额','number',{min:.01,step:.01})]:[]),note('审核意见',2000)],`/applications/${a.id}/review`,{decision:decision||(a.kind==='返还'?'通过':'受理'),amount:a.amount||''},'',x=>x,()=>[{label:'申请人',value:businessName(a.applicant_name)||'历史身份待核验'},...(a.kind==='返还'?[{label:'本人收款账户',value:a.payee||'待核验'},...fundSummary(a.originalFunds)]:[{label:'本人账户剩余冻结',value:money(a.originalFunds?.remaining)}])])}
function arriveForm(v){form('记录到场',[f('lat','纬度','number',{min:-90,max:90,step:.000001,required:true}),f('lng','经度','number',{min:-180,max:180,step:.000001,required:true}),f('time','到场时间','datetime-local',{required:true}),f('simulated','手动录入位置','checkbox')],`/visits/${v.id}/arrive`,{lat:'30.300001',lng:'120.100001',time:localTime(),simulated:true},'确认坐标与到场时间后提交，每项任务保存一次到场记录。')}
function feedbackForm(v){form('提交劝阻结果',[f('process','现场过程与谈话要点','textarea',{required:true}),f('result','劝阻结果','select',{required:true,options:['已完成','未完成']}),f('reason','未完成原因','textarea',{max:1000}),attachment(true)],`/visits/${v.id}/feedback`,{result:'已完成'},'过程说明与至少一份现场材料齐全后，才能回传中心。')}
function campaignForm(){form('派发社区宣防任务',[f('title','任务标题','text',{required:true}),f('communityId','负责社区','select',{required:true,options:option(meta.value.communities)}),f('dueAt','截止时间','datetime-local',{required:true}),f('description','任务说明','textarea',{required:true})],'/campaigns')}
function checkinForm(c){form('宣传活动打卡',[f('form','宣传形式','select',{required:true,options:['入户宣传','集中讲座','现场咨询','线上宣传']}),f('time','活动时间','datetime-local',{required:true,min:c.created_at,max:c.due_at<localTime()?c.due_at:localTime()}),f('sessions','开展场次','number',{min:1,step:1,required:true}),f('people','触达人次','number',{min:0,step:1,required:true}),f('note','活动说明','textarea',{max:1000})],`/campaigns/${c.id}/checkin`,{time:localTime(),sessions:1,people:0,requestKey:crypto.randomUUID()},'触达人数按人次记录，与上门任务结果分开统计。')}
function articleForm(a={}){const categories=[...new Set([...articleCategories,...(a.category?[articleCategory(a.category)]:[])])];form(a.id?'编辑知识文章':'新建知识文章',[f('title','标题','text',{required:true,wide:true}),f('category','分类','select',{required:true,options:categories}),f('state','发布状态','select',{required:true,options:['草稿','已发布','已下线']}),f('summary','摘要','textarea',{required:true,max:300,rows:3}),f('body','正文','textarea',{required:true,max:20000,rows:8})],'/articles'+(a.id?'/'+a.id:''),{state:'草稿',...a,category:articleCategory(a.category)})}
function editBlacklist(a={}){form(a.id?'维护风险名单':'新增风险名单',[f('kind','类型','select',{options:['号码','账户','网址'],required:true}),f('value','匹配内容','text',{required:true}),f('source','来源依据','text',{required:true}),f('enabled','启用','checkbox')],'/blacklist'+(a.id?'/'+a.id:''),{kind:'号码',enabled:true,...a})}
function editUser(a={}){form(a.id?'维护账号':'新增账号',[f('username','登录账号','text',{required:true}),f('displayName','显示名称','text',{required:true}),f('role','业务角色','select',{required:true,options:Object.entries(roleNames).map(([value,label])=>({value,label}))}),f('password',a.id?'新密码（不修改则留空）':'初始密码','password',{required:!a.id}),f('orgId','支付机构归属','select',{options:option(meta.value.orgs)}),f('communityId','网格社区归属','select',{options:option(meta.value.communities)}),f('victimId','已核验实名人员关联','select',{options:option(meta.value.victims)}),f('verified','身份资料已关联','checkbox'),f('enabled','启用账号','checkbox'),f('admin','中心管理权限','checkbox')],'/users'+(a.id?'/'+a.id:''),{username:a.username||'',displayName:a.display_name||'',role:a.role||'PUBLIC',enabled:a.enabled??true,verified:a.role==='PUBLIC'&&a.verified,admin:a.admin||false,orgId:a.org_id||'',communityId:a.community_id||'',victimId:a.victim_id||''},'角色由账号记录决定；机构与网格角色必须有对应归属。')}
function configForm(){const c=meta.value.config||{};form('发布新规则版本',[...['金额','时段','异地','黑名单','异常行为'].map((label,i)=>f('w'+i,label+'权重','number',{min:1,max:100,step:1,required:true,unit:'%',section:i===0?'评分权重':undefined})),...Object.entries({medium:'中风险阈值',high:'高风险阈值',mergeHours:'归并窗口（小时）',freezeHours:'冻结时限（小时）',extensionHours:'每次延期（小时）',maxExtensions:'延期次数上限',timeoutMinutes:'机构超时（分钟）'}).map(([key,label])=>f(key,label,'number',{min:0,step:1,required:true,section:key==='medium'?'风险阈值':key==='mergeHours'?'时效设置':undefined}))],'/configs',{...c,...Object.fromEntries((c.weights||[]).map((v,i)=>['w'+i,v]))},'五项权重之和必须为100，已生效指令的到期时间保持不变。',data=>({...data,weights:[0,1,2,3,4].map(i=>Number(data['w'+i]))}))}
function correctionForm(c){form('申请回执更正',[f('result','更正后的结果','select',{required:true,options:['全额执行','部分执行','拒绝执行']}),f('amount','更正后实际金额','number',{min:0,step:.01,required:true}),f('reason','更正原因','textarea',{required:true,max:1000})],`/commands/${c.id}/correction`,{amount:c.actual},'保留原回执。已有后续返还或解除依赖时，中心不能直接更正。')}
const canCreate=computed(()=>({reports:role.value==='PUBLIC'||isCenter.value,campaigns:isCenter.value,articles:isCenter.value,users:isAdmin.value,blacklist:isAdmin.value,configs:isAdmin.value,people:isAdmin.value,banks:isAdmin.value}[page.value]))
function create(){({reports:reportForm,campaigns:campaignForm,articles:articleForm,users:editUser,blacklist:editBlacklist,configs:configForm,people:personForm,banks:bankForm}[page.value])?.()}
const d=computed(()=>detail.value?.data||{})
const pendingTargets=computed(()=>(d.value.targetCandidates||[]).filter(t=>!(d.value.targets||[]).some(x=>x.bank_id===t.id)))
const articleParagraphs=computed(()=>String(d.value.body||'').split(/\r?\n/).map(text=>text.trim()).filter(Boolean))
const primaryRoute=computed(()=>({CENTER:'alerts',PAYMENT:'commands',GRID:'visits',PUBLIC:'reports'}[role.value]))
const dashboardColumns=computed(()=>role.value==='CENTER'?[{key:'code',label:'预警编号'},{key:'level',label:'风险',badge:true},{key:'score',label:'评分'},{key:'state',label:'办理状态',badge:true}]:[{key:'code',label:'业务编号'},{key:'state',label:'当前状态',badge:true},{key:'created_at',label:'创建时间'}])
const detailPairs=computed(()=>{const fields={code:'业务编号',kind:'业务类型',state:detail.value?.type==='applications'?'申请状态':'当前状态',processing:'研判状态',level:'风险等级',score:'规则评分',created_at:'创建时间',expires_at:'到期时间',deadline_at:'本次办理截止',person:'服务对象',victim_name:'已核验受害人',applicant_name:'申请人',payee:'本人收款账户',phone:'联络号码',arrived_at:'到场时间',result:'办理结果',returned_at:'回传时间',requested:'指令金额',actual:'实际执行',remaining:'剩余冻结',returned:'累计返还',reserved:'待执行占用',amount:detail.value?.type==='reports'?'涉及交易金额':'申请金额',approved:'核定金额',extension_count:'延期次数',source:'来源依据',enabled:'启用状态',value:detail.value?.type==='blacklist'?'匹配内容':'举报线索',transactionTime:'交易时刻',updated_at:'更新时间'};return Object.entries(fields).filter(([key])=>d.value[key]!=null&&!(key==='approved'&&d.value.fundsProgress)&&!(detail.value?.type==='commands'&&d.value.kind!=='止付'&&(['remaining','returned','reserved','extension_count'].includes(key)||key==='deadline_at'&&!['已送达','受理中'].includes(d.value.state)))).map(([key,label])=>({key,label,badge:['state','processing','level'].includes(key),value:['requested','actual','remaining','returned','reserved','amount','approved'].includes(key)?money(d.value[key]):fmt(['person','victim_name','applicant_name'].includes(key)?businessName(d.value[key]):d.value[key])}))})
</script>

<template>
 <div v-if="!session.ready" class="initial-loading">正在连接反诈协同处置平台…</div>
 <PublicPortal v-else-if="!user" :paused="!!(detail||modal||receiptResult||loginOpen)" :page="page" :articles="rows" :busy="busy" :error="error" :query-result="queryResult" :query-busy="queryBusy" v-model:code="queryCode" v-model:token="queryToken" @navigate="go" @report="reportForm" @login="openLogin" @article="openDetail('articles',$event)" @query="query" @refresh="refresh"/>
 <div v-else class="workspace">
  <aside :class="['sidebar',{open:mobile}]">
   <a href="#dashboard" class="brand"><span class="brand-symbol"><AppIcon name="shield" :size="24"/></span><span>反诈协同<small>业务处置工作台</small></span></a>
   <div class="workspace-tag"><span class="status-dot"></span>{{roleNames[role]||'公共服务'}}</div>
   <nav aria-label="工作台导航"><section v-for="group in navGroups" :key="group.label" class="nav-group"><p class="nav-section">{{group.label}}</p><button v-for="m in group.items" :key="m.id" :class="{active:page===m.id}" :aria-current="page===m.id?'page':undefined" @click="go(m.id);mobile=false"><AppIcon :name="navIcons[m.id]"/><span>{{m.label}}</span></button></section></nav>
   <div class="sidebar-footer"><div class="avatar">{{businessName(user?.displayName).slice(0,1)}}</div><div class="user-caption"><strong>{{businessName(user?.displayName)}}</strong><small>{{user?.username||'公共服务入口'}}</small></div><button v-if="user" class="icon-button logout" aria-label="退出登录" @click="logout"><AppIcon name="logout" :size="18"/></button><button v-else class="text-button" @click="go('welcome')">登录</button></div>
  </aside>
  <div v-if="mobile" class="nav-shade" @click="mobile=false"></div>
  <div class="main-area"><header class="topbar"><div class="breadcrumb-row"><button class="icon-button mobile-menu" aria-label="打开菜单" @click="mobile=!mobile;accountMenu.open=false"><AppIcon name="menu" :size="20"/></button><span class="muted">{{roleNames[role]||'公共服务'}}</span><AppIcon name="chevron" :size="13"/><strong>{{title}}</strong></div><div class="topbar-meta"><span class="topbar-date">{{new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}}</span><details ref="accountMenu" class="mobile-account" @keydown.esc="accountMenu.open=false" @focusout="!$event.currentTarget.contains($event.relatedTarget)&&(accountMenu.open=false)"><summary aria-label="查看当前账号"><AppIcon name="user" :size="18"/><span>账号</span></summary><div class="account-popover"><strong>{{businessName(user.displayName)}}</strong><span>{{user.username}} · {{roleNames[role]}}</span><button @click="logout"><AppIcon name="logout" :size="16"/>退出登录</button></div></details></div></header>
  <main class="content"><div class="page-heading"><div><h1>{{title}}</h1></div><div class="heading-actions"><button v-if="page==='dashboard'" class="primary" @click="role==='PUBLIC'?reportForm():go(primaryRoute)">{{role==='PUBLIC'?'提交举报':'查看待办'}}<AppIcon name="arrow" :size="16"/></button><button v-if="user" :disabled="busy" @click="refresh"><AppIcon name="refresh" :size="16"/>刷新</button><button v-if="canCreate" class="primary" @click="create"><AppIcon name="plus" :size="16"/>{{page==='configs'?'发布新版本':page==='reports'?'提交线索':'新建'}}</button><button v-if="!user" class="primary" @click="reportForm"><AppIcon name="plus" :size="16"/>提交匿名举报</button></div></div>
   <div v-if="error" class="error-box page-error" role="alert">{{error}}<button class="text-button" @click="refresh">重试</button></div><div v-if="busy" class="loading-bar" aria-label="正在加载"></div>
   <template v-if="page==='dashboard'">
    <div v-if="role==='PUBLIC'" class="action-strip"><div><strong>{{businessName(user.displayName)}} · 身份资料</strong><span>{{user.verified?'实名已核验，按案件与账户归属办理':'资料待核验，请联系中心管理员'}}</span></div><span class="badge" :class="user.verified?'green':'amber'">{{user.verified?'已关联':'待核验'}}</span></div>
    <div class="stats-filter"><span>统计范围</span><input type="date" v-model="from" aria-label="统计开始日期"><span>至</span><input type="date" v-model="to" aria-label="统计结束日期"><button class="small" @click="refresh">应用</button><a :href="exportUrl" class="export-link"><AppIcon name="download" :size="16"/>导出汇总</a></div>
    <section v-if="stats.metrics.length" class="metric-grid" :style="{'--metric-columns':Math.min(4,stats.metrics.length)}"><article v-for="m in stats.metrics" :key="m.label" class="metric-card"><div><span>{{m.label}}</span></div><strong>{{fmt(m.value)}}<small>{{m.unit}}</small></strong></article></section>
    <section class="dashboard-grid"><article class="panel"><div class="panel-heading"><div><h3>业务受理趋势</h3></div><span class="chart-caption">最近 14 个有记录日期</span></div><div v-if="stats.daily.length" class="bar-chart"><div v-for="point in stats.daily.slice(-14)" class="bar-column" :title="point.day+'：'+point.value+'条'"><span>{{point.value}}</span><div :style="{height:Math.max(4,point.value/Math.max(...stats.daily.map(d=>d.value))*120)+'px'}"></div><small>{{point.day.slice(5)}}</small></div></div><div v-else class="empty compact">当前日期范围内暂无业务记录</div></article><article class="panel"><div class="panel-heading"><h3>{{isCenter?'风险分布':'常用功能'}}</h3></div><div v-if="isCenter" class="risk-list"><div v-for="level in ['高','中','低']"><span class="badge" :class="statusTone(level)">{{level}}风险</span><div class="risk-track"><i :class="statusTone(level)" :style="{width:(stats.risks.find(r=>r.label===level)?.value||0)/Math.max(1,stats.risks.reduce((a,r)=>a+Number(r.value),0))*100+'%'}"></i></div><strong>{{stats.risks.find(r=>r.label===level)?.value||0}}</strong></div></div><div v-else class="quick-links"><button v-for="link in quickLinks" :key="link.id" @click="go(link.id)"><AppIcon :name="navIcons[link.id]" :size="18"/><span><strong>{{link.label}}</strong><small>{{link.hint}}</small></span><AppIcon name="chevron" :size="14"/></button></div></article></section>
    <section class="panel"><div class="panel-heading"><div><h3>{{role==='PUBLIC'?'最近提交':'重点关注'}}</h3></div><button class="text-button" @click="go(primaryRoute)">查看全部<AppIcon name="arrow" :size="15"/></button></div><DataTable :rows="rows.slice(0,10)" :columns="dashboardColumns" @select="openDetail(primaryRoute,$event)"/></section>
    <section v-if="stats.byKind?.length" class="panel summary-breakdown"><h3>指令分类与有效回执</h3><div class="command-summary-grid"><article v-for="k in stats.byKind" :key="k.label" class="command-summary"><header><span>{{k.label}}</span><strong>{{k.value}}<small> 条</small></strong></header><dl><div><dt>申请金额</dt><dd>{{money(k.requested)}}</dd></div><div><dt>实际执行</dt><dd>{{money(k.actual)}}</dd></div></dl></article></div><div v-if="stats.byResult?.length" class="receipt-summary"><span>回执结果</span><span v-for="r in stats.byResult" :key="r.label">{{r.label}}<strong>{{r.value}}</strong>条</span></div></section>
   </template>
    <section v-else-if="page==='articles'" class="panel knowledge-panel"><KnowledgeList :articles="rows" :manage="isCenter" @select="openDetail('articles',$event)"/></section>
    <section v-else-if="page==='configs'" class="panel"><div class="panel-heading"><div><h3>规则版本历史</h3><p>默认采用五因子加权，权重总和为100。</p></div></div><article v-for="c in rows" :key="c.id" class="config-version"><header><h3>版本 {{c.id}}</h3><div class="config-meta"><time :datetime="c.created_at">{{fmt(c.created_at)}}</time><span>{{c.display_name}}</span></div></header><div class="weight-row"><div v-for="(w,i) in c.data.weights" :key="i"><strong>{{w}}<small>%</small></strong><span>{{['金额','时段','异地','黑名单','异常行为'][i]}}</span></div></div><dl class="config-details"><div><dt>高风险阈值</dt><dd>≥ {{c.data.high}} 分</dd></div><div><dt>中风险阈值</dt><dd>≥ {{c.data.medium}} 分</dd></div><div><dt>线索归并时限</dt><dd>{{c.data.mergeHours}} 小时</dd></div><div><dt>冻结时限</dt><dd>{{c.data.freezeHours}} 小时</dd></div><div><dt>最多延期</dt><dd>{{c.data.maxExtensions}} 次</dd></div><div><dt>机构响应时限</dt><dd>{{c.data.timeoutMinutes}} 分钟</dd></div></dl></article></section>
   <template v-else-if="page==='applications'"><div v-if="role==='PUBLIC'" class="action-strip"><div><strong>后续办理</strong><span>返还由受害人申请；误冻结申诉由冻结账户户主提出</span></div><button @click="applicationForm('返还')">申请资金返还</button><button class="primary" @click="applicationForm('申诉')">提交误冻结申诉</button></div><section class="panel"><DataTable :key="page" :server="pagination" :resource="page" @query="listChanged" :columns="columns" :rows="rows" @select="select"/></section></template>
   <template v-else-if="page==='notices'"><section class="panel"><h3>指令时效与督办</h3><DataTable :server="pagination" :resource="page" @query="listChanged" :columns="columns" :rows="rows" @select="select"/></section><section class="panel summary-breakdown"><div class="panel-heading"><h3>上门任务督办</h3><span class="chart-caption">超期未回传与劝阻未完成</span></div><DataTable :rows="visitAttention" :columns="[{key:'code',label:'任务编号'},{key:'community_name',label:'社区'},{key:'assignee',label:'执行人'},{key:'attention',label:'督办原因',badge:true},{key:'due_at',label:'要求完成时间'}]" @select="openDetail('visits',$event)"/></section></template>
   <section v-else-if="columns.length" class="panel"><IntegrityPanel v-if="page==='banks'&&role!=='PUBLIC'" key="funds" kind="funds"/><IntegrityPanel v-if="page==='logs'&&isAdmin" key="audit" kind="audit"/><DataTable :key="page" :server="pagination" :resource="page" @query="listChanged" :columns="columns" :rows="rows" :selectable="page==='banks'?isAdmin:!['people','logs'].includes(page)" @select="select"/></section>
  </main><footer class="workspace-footer"><span>反诈协同处置平台</span></footer></div>
 </div>

  <div v-if="detail" class="drawer-backdrop" @click.self="closeDetail"><section class="detail-drawer" :class="{'article-drawer':detail.type==='articles'}" role="dialog" aria-modal="true" :aria-label="detail.type==='articles'?'文章详情':'业务详情'" tabindex="-1"><header class="drawer-header"><div><p class="eyebrow">{{({alerts:'研判详情',reports:'举报详情',commands:'指令详情',visits:'任务详情',applications:'申请详情',articles:'知识文章',campaigns:'宣防详情',notices:'督办详情',corrections:'更正详情',blacklist:'风险名单详情',banks:'账户详情'})[detail.type]}}</p><h2>{{d.title||d.code||(detail.type==='blacklist'?'风险名单':detail.type==='banks'?'资金账户':'办理记录')}}</h2><div v-if="detail.type==='articles'" class="article-reading-meta"><span class="article-category">{{articleCategory(d.category)}}</span><span v-if="d.updated_at" class="article-updated">更新于 <time :datetime="d.updated_at">{{fmt(d.updated_at)}}</time></span><span v-if="isCenter" class="badge" :class="statusTone(d.state)">{{d.state}}</span></div></div><button class="icon-button" aria-label="关闭详情" @click="closeDetail"><AppIcon name="close" :size="20"/></button></header><div class="drawer-body">
  <div v-if="error" class="error-box" role="alert">{{error}}</div>
  <p v-if="detail.loading" role="status">正在加载详情…</p><div v-if="!detail.loading" class="detail-actions">
   <template v-if="detail.type==='alerts'"><button v-if="isCenter&&!['已闭环','已驳回','已作废'].includes(d.state)" @click="form('作废预警及未执行任务',[note('作废原因')],`/alerts/${d.id}/void`,{},'仅允许机构未受理、网格未到场的记录作废；所有原始材料和日志继续保留。')">作废</button><button v-if="!['已闭环','已驳回','已作废'].includes(d.state)" class="primary" @click="reviewForm(d)">人工复核 / 补录</button><button v-if="!['已闭环','已驳回','已作废'].includes(d.state)" @click="linkAccountForm(d)">核验关联账户</button><button v-if="d.freeze_review_ready&&d.targets?.length" @click="dispatchForm(d)">联动派发</button><button v-if="d.freeze_review_ready" @click="form('派发上门核查',[note('上门核查说明')],`/alerts/${d.id}/visit`,{},'尚未查明资金账户时，可以先核查当事人并上门劝阻；此操作不会创建止付。')">派发上门核查</button><button v-if="['已派单','处置中'].includes(d.state)" @click="form('确认本轮办结',[note('办结意见与异常处理决定')],`/alerts/${d.id}/close`)">确认办结</button></template>
   <template v-if="detail.type==='commands'"><button v-if="role==='PAYMENT'&&d.actions?.accept" class="primary" @click="action(`/commands/${d.id}/accept`)">受理指令</button><button v-if="role==='PAYMENT'&&d.actions?.receipt" class="primary" @click="receiptForm(d)">核查后提交回执</button><button v-if="role==='PAYMENT'&&d.actions?.correct" @click="correctionForm(d)">申请更正</button><button v-if="isCenter&&d.actions?.extend" @click="form('申请延期',[note('延期理由')],`/commands/${d.id}/extend`)">延期</button><button v-if="isCenter&&d.actions?.retry" @click="form('核实后重发',[note('重新核实意见与重发理由')],`/commands/${d.id}/retry`)">复核重发</button><button v-if="isAdmin&&['生效中','已延期','已送达','受理中'].includes(d.state)" @click="form('推进时效节点',[f('node','检查节点','select',{required:true,options:['已送达','受理中'].includes(d.state)?['超时']:['24小时','2小时','到期']})],`/commands/${d.id}/simulate`,{},'将当前指令推进至选定的时效节点，到期会更新账本并保存操作记录。')">时效检查</button></template>
   <template v-if="detail.type==='reports'"><button v-if="isCenter&&d.processing==='人工待研判'" class="primary" :disabled="retryingReport" @click="retryReport(d)">{{retryingReport?'正在重新研判…':'重新研判'}}</button><button v-if="isCenter&&d.alert_id" @click="openDetail('alerts',{id:d.alert_id})">查看关联预警</button><button @click="form('管理查询凭证',[f('mode','操作','select',{required:true,options:['重置','停用']}),note('操作原因')],`/reports/${d.id}/query-token`,{mode:'重置'},'原凭证将立即失效。重置后请保存新的查询凭证。')">管理查询凭证</button></template><template v-if="detail.type==='visits'"><button v-if="role==='GRID'&&d.state==='待接收'" class="primary" @click="action(`/visits/${d.id}/claim`)">接收任务</button><button v-if="isCenter&&['待接收','待上门'].includes(d.state)" @click="form('改派网格任务',[f('assigneeId','本社区执行人','select',{required:true,options:option((meta.gridUsers||[]).filter(g=>g.community_id===d.community_id),'id','display_name')}),note('改派原因')],`/visits/${d.id}/assign`)">指定 / 改派</button><button v-if="role==='GRID'&&d.assignee_id===user.id&&d.state==='待上门'" class="primary" @click="arriveForm(d)">记录到场</button><button v-if="role==='GRID'&&d.assignee_id===user.id&&d.state==='劝阻中'" class="primary" @click="feedbackForm(d)">回传结果</button><button v-if="['已回传','已归档'].includes(d.state)&&(isCenter||d.assignee_id===user.id)" @click="form('追加说明',[note()],`/visits/${d.id}/append`)">追加说明</button></template>
   <template v-if="detail.type==='applications'"><button v-if="isCenter&&['待核定','待受理','审核中'].includes(d.state)" class="primary" @click="applicationReview(d)">中心审核</button><button v-if="role==='PUBLIC'&&d.state==='驳回待补'" class="primary" @click="form('补正申请材料',[f('reason','补充说明','textarea',{required:true}),attachment(true)],`/applications/${d.id}/supplement`)">补交材料</button></template>
   <template v-if="detail.type==='campaigns'"><button v-if="isCenter&&d.state==='已发布'" @click="form('结束宣传任务',[f('state','处理结果','select',{required:true,options:['已完成','已取消']}),note('结束说明')],`/campaigns/${d.id}/finish`,{state:'已完成'},'保留全部活动记录；任务结束后不能再打卡。')">完成 / 取消任务</button><button v-if="role==='GRID'&&d.state==='已发布'" class="primary" @click="checkinForm(d)">宣传打卡</button></template><button v-if="detail.type==='articles'&&isCenter" @click="articleForm(d)">编辑文章</button>
   <button v-if="detail.type==='notices'&&!d.resolved" class="primary" @click="form('记录督办处理',[note('处理决定')],`/notices/${d.id}/resolve`)">处理督办</button><button v-if="detail.type==='corrections'&&isCenter&&d.state==='待审核'" class="primary" @click="form('审核回执更正',[f('approve','批准更正','checkbox'),note()],`/corrections/${d.id}/review`)">审核更正</button>
  </div>
  <button v-if="detail.type==='notices'" class="linked-record" @click="openDetail('commands',{id:d.command_id})">查看关联指令与处理进度<AppIcon name="chevron" :size="16"/></button><section v-if="detail.type==='corrections'&&!detail.loading" class="detail-section"><h3>回执更正对照</h3><table class="comparison-table"><thead><tr><th>项目</th><th>申请时的有效回执</th><th>本次更正申请</th></tr></thead><tbody><tr><th>执行结果</th><td>{{d.originalReceipt?.result||'未保存快照'}}</td><td>{{d.new_result}}</td></tr><tr><th>实际金额</th><td>{{d.originalReceipt?money(d.originalReceipt.amount):'—'}}</td><td>{{money(d.new_amount)}}</td></tr><tr><th>说明</th><td>{{d.originalReceipt?.reason||'—'}}</td><td>{{d.reason}}</td></tr></tbody></table><p v-if="!d.originalReceipt" class="muted">旧记录未保存申请时的回执快照，可查看原指令中的回执版本历史。</p><button class="linked-record" @click="openDetail('commands',{id:d.command_id})">查看原指令与回执历史<AppIcon name="chevron" :size="16"/></button></section>
  <p v-if="detail.type==='commands'&&d.kind==='止付'&&['已闭环','已驳回','已作废'].includes(d.alert_state)&&['未处理','拒绝执行'].includes(d.state)" class="warning-box">关联预警已结束，新的止付需另行受理预警。已有冻结的返还、申诉和解除仍按各自规则办理。</p>
  <div v-if="!detail.loading&&isCenter&&detail.type==='commands'&&d.kind==='止付'&&['未处理','拒绝执行','已拒绝'].includes(d.state)&&!['已闭环','已驳回','已作废'].includes(d.alert_state)&&(!d.freeze_review_ready||!d.target_verified)" class="warning-box"><p>{{!d.target_verified?'此账户与线索的关系尚未核验，请先回到预警核验关联。':d.alert_needs_review?'线索或账户关联尚未完成补充复核，暂不能重发止付。':'尚无有效的人工复核通过记录，暂不能重发止付。'}}</p><button @click="openDetail('alerts',{id:d.alert_id})">前往预警复核</button></div>
  <p v-if="d.attention" class="warning-box">{{d.attention}}。中心可从本任务指定执行人或记录处理意见；超期任务仍须完成回传。</p><div v-if="d.needs_review" class="warning-box">线索或账户关联有更新，请完成人工复核。原有执行任务继续处理。</div><dl v-if="detail.type!=='articles'&&detailPairs.length" class="details-grid"><div v-for="pair in detailPairs" :key="pair.key" class="detail-field"><dt>{{pair.label}}</dt><dd><span v-if="pair.badge" class="badge" :class="statusTone(String(pair.value))">{{pair.value}}{{pair.key==='level'?'风险':''}}</span><span v-else>{{pair.value}}</span></dd></div></dl>
  <p v-if="detail.type==='commands'&&d.deadline_passed" class="warning-box">本次办理期限已过，不能继续受理、执行或延期；到期释放及超时状态会由系统同步处理。</p><section v-if="d.bank" class="info-box"><h4>账户核查</h4><dl class="record-facts"><div><dt>账户户名</dt><dd>{{businessName(d.bank.holder)}}</dd></div><div><dt>账户号码</dt><dd class="mono">{{d.bank.account}}</dd></div><div v-if="d.bank.available!=null"><dt>可用余额</dt><dd>{{money(d.bank.available)}}</dd></div></dl></section>
  <template v-for="(label,key) in {description:'情况说明',reason:'原因与说明',process_text:'现场过程',review_note:'复核意见',exception_note:'办结意见',note:'审核或处理意见',message:'提醒内容',resolution:'处理决定'}" :key="key"><section v-if="d[key]&&!(detail.type==='corrections'&&key==='reason')" class="detail-section"><h3>{{label}}</h3><p class="pre-wrap">{{d[key]}}</p></section></template>
  <article v-if="detail.type==='articles'" class="article-reader"><img class="article-illustration" :src="articleArt(d)" alt=""/><p v-if="d.summary" class="article-summary">{{d.summary}}</p><div class="article-prose"><p v-for="(paragraph,index) in articleParagraphs" :key="index">{{paragraph}}</p></div></article>
  <section v-if="detail.type==='banks'" class="detail-section"><h3>账户归属已核验</h3><dl class="record-facts"><div><dt>银行账户</dt><dd>{{d.account}}</dd></div><div><dt>实名户主</dt><dd>{{businessName(d.holder)}}</dd></div><div><dt>所属机构</dt><dd>{{businessName(d.org_name)}}</dd></div><div><dt>可用余额</dt><dd>{{money(d.available)}}</dd></div></dl><p>已核验账户归属不能直接变更。如开户资料有误，请核对原始凭据后重新登记正确账户。</p></section>
  <section v-if="d.fundsProgress" class="detail-section"><div class="detail-section-heading"><h3>资金办理</h3><span class="badge" :class="statusTone(d.fundsProgress.state)">{{d.fundsProgress.state}}</span></div><dl class="record-facts"><div><dt>核定金额</dt><dd>{{d.approved==null?'—':money(d.approved)}}</dd></div><div><dt>实际入账</dt><dd>{{money(d.fundsProgress.credited)}}</dd></div></dl><p>{{d.fundsProgress.note}}</p></section>
  <section v-if="d.progress" class="detail-section progress-section"><h3>当前办理进度</h3><span class="badge" :class="statusTone(d.progress.state)">{{d.progress.state}}</span></section>
  <section v-if="d.application" class="detail-section"><div class="detail-section-heading"><h3>关联申请</h3><span class="mono">{{d.application.code}}</span></div><p v-if="d.application.reason">{{d.application.reason}}</p><p v-if="d.application.note">{{d.application.note}}</p><dl v-if="d.application.kind==='返还'&&d.application.payee" class="record-facts"><div><dt>收款账户</dt><dd>{{d.application.payee}}</dd></div></dl><div class="attachment-list"><a v-for="file in d.application.attachments" :key="file.id" :href="'/api/attachments/'+file.id"><AppIcon name="attachment" :size="16"/><span>{{file.filename}}</span><AppIcon name="download" :size="16"/></a></div></section>
  <section v-if="d.attachments?.length||d.reportMaterials?.length" class="detail-section"><h3>相关材料</h3><div class="attachment-list"><a v-for="file in [...(d.attachments||[]),...(d.reportMaterials||[])]" :key="file.id" :href="'/api/attachments/'+file.id"><AppIcon name="attachment" :size="16"/><span>{{file.filename}}</span><AppIcon name="download" :size="16"/></a></div></section>
  <section v-if="detail.type==='alerts'&&!detail.loading" class="detail-section"><h3>线索与资金账户</h3><p v-if="!d.targets?.length" class="muted">尚无经核验的资金账户。先核查线索，或派发上门核查；不能直接止付任意账户。</p><article v-for="t in d.targets" :key="t.bank_id" class="clue-card"><header><strong>{{t.account}} · {{businessName(t.holder)}}</strong><span class="tag">已核验关联</span></header><p>{{t.kind}}：{{t.clue}} · {{t.report_code}}</p><p>{{t.basis}}</p><footer class="record-meta">{{t.verified_by}} · {{fmt(t.verified_at)}}</footer><button v-if="!['已闭环','已驳回','已作废'].includes(d.state)&&!d.commands?.some(c=>c.bank_id===t.bank_id)" class="text-button" @click="form('撤销未使用账户关联',[note('撤销原因')],`/alerts/${d.id}/accounts/${t.bank_id}/remove`)">撤销此关联</button></article><template v-if="!['已闭环','已驳回','已作废'].includes(d.state)"><h4 v-if="pendingTargets.length">待核实的关联提示</h4><button v-for="t in pendingTargets" :key="t.id+'-'+t.report_id" class="linked-record" @click="linkAccountForm(d,t)"><span>{{t.account}} · {{businessName(t.holder)}} · {{t.basis}}</span><span>核验</span></button></template></section>
  <section v-if="d.reports?.length" class="detail-section"><h3>关联原始线索</h3><article v-for="r in d.reports" :key="r.id" class="clue-card"><header><strong>{{r.code}}</strong><span class="tag">{{businessName(r.source)}}</span></header><dl class="record-facts"><div><dt>{{r.kind}}</dt><dd>{{r.value}}</dd></div><div><dt>归一化线索</dt><dd>{{r.normalized}}</dd></div><div><dt>举报人与事件关系（自述）</dt><dd>{{r.reporterRelation||'未填写'}}</dd></div><div><dt>交易金额</dt><dd>{{r.amount==null||r.amount===''?'未提供':money(r.amount)}}</dd></div><div><dt>交易时刻</dt><dd>{{r.transactionTime||'未提供'}}</dd></div><div><dt>异地交易</dt><dd>{{r.remote?'是':'否'}}</dd></div></dl><p class="pre-wrap">{{r.description}}</p><div class="attachment-list"><a v-for="file in r.attachments" :key="file.id" :href="'/api/attachments/'+file.id"><AppIcon name="attachment" :size="16"/><span>{{file.filename}}</span><AppIcon name="download" :size="16"/></a></div></article></section>
  <section v-if="d.scores?.length" class="detail-section"><h3>评分依据与版本</h3><details v-for="(score,i) in d.scores" class="score-record" :open="i===0"><summary><strong>{{score.score}} 分 · {{score.level}}风险</strong><span>线索 #{{score.report_id}} · 配置 v{{score.config_id}}</span></summary><table><thead><tr><th>因子</th><th>原始分</th><th>权重</th><th>加权贡献</th></tr></thead><tbody><tr v-for="factor in score.details.details"><td>{{factor.name}}</td><td>{{factor.factor}}</td><td>{{factor.weight}}%</td><td>{{factor.contribution}}</td></tr></tbody></table><p v-for="hit in score.details.matches" class="muted">匹配依据：{{hit.kind}} · {{hit.source}}</p><p v-if="score.details.fallback" class="warning-box">配置无效时已回退默认权重。</p><small>总分按非负数四舍五入；归并取关联线索最高总分。</small></details></section>
  <section v-if="d.receipts?.length" class="detail-section"><h3>回执记录</h3><article v-for="r in d.receipts" :key="r.id" class="clue-card"><header><strong>版本 {{r.version}} · {{r.result}}</strong><span class="badge" :class="r.valid?'green':'gray'">{{r.valid?'当前有效':'历史版本'}}</span></header><dl class="record-facts"><div><dt>实际金额</dt><dd>{{money(r.amount)}}</dd></div><div><dt>凭证编号</dt><dd>{{r.voucher}}</dd></div></dl><p v-if="r.reason" class="pre-wrap">{{r.reason}}</p><footer class="record-meta"><span>{{r.display_name}}</span><time :datetime="r.created_at">{{fmt(r.created_at)}}</time></footer><div class="attachment-list"><a v-for="file in r.attachments" :key="file.id" :href="'/api/attachments/'+file.id"><AppIcon name="attachment" :size="16"/><span>{{file.filename}}</span><AppIcon name="download" :size="16"/></a></div></article></section>
  <section v-if="d.commands?.length" class="detail-section"><h3>关联指令</h3><button v-for="c in d.commands" class="linked-record" @click="openDetail('commands',c)"><span>{{c.code}} · {{c.kind}}</span><span class="badge" :class="statusTone(c.state)">{{c.state}}</span><AppIcon name="chevron" :size="16"/></button></section>
  <section v-if="d.visits?.length" class="detail-section"><h3>关联上门任务</h3><button v-for="v in d.visits" class="linked-record" @click="openDetail('visits',v)"><span>{{v.code}}</span><span class="badge" :class="statusTone(v.state)">{{v.state}}</span><AppIcon name="chevron" :size="16"/></button></section>
  <section v-if="d.records" class="detail-section"><h3>宣传活动记录</h3><article v-for="r in d.records" class="clue-card"><strong>{{r.form}} · {{r.sessions}}场 · {{r.people}}人次</strong><p>{{r.note}}</p><small>{{r.display_name}} · {{fmt(r.occurred_at)}}</small></article><p v-if="!d.records.length" class="muted">暂无打卡记录。</p></section>
  <section v-if="d.assessments?.length" class="detail-section"><h3>人工复核记录</h3><article v-for="r in d.assessments" class="clue-card"><strong>{{r.decision}} · {{r.display_name}}</strong><p>{{r.note}}</p><small>{{fmt(r.created_at)}}</small></article></section>
  <section v-if="d.timeline?.length" class="detail-section"><h3>办理时间线</h3><ol class="timeline"><li v-for="(t,i) in d.timeline" :key="i"><span class="timeline-dot"></span><div class="timeline-heading"><strong>{{t.action}}</strong><span v-if="t.new_state" class="badge" :class="statusTone(t.new_state)">{{t.new_state}}</span></div><time :datetime="t.created_at">{{fmt(t.created_at)}}</time><p v-if="t.note">{{t.note}}</p></li></ol></section>
 </div></section></div>
 <LoginDialog v-if="loginOpen" v-model:role="loginRole" v-model:username="username" v-model:password="password" :busy="loginBusy" :error="loginError" @close="loginOpen=false;loginError=''" @submit="login" @account="demo"/>
 <FormDialog v-if="modal" :key="modal.title" v-bind="modal" @close="modal=null" @done="done" @conflict="refresh"/>
 <div v-if="receiptResult" class="modal-backdrop"><section class="dialog receipt-success" role="dialog" aria-modal="true" aria-label="凭证信息"><span class="success-icon"><AppIcon name="check" :size="28"/></span><h2>{{receiptResult.credentialReset?'查询凭证已重置':'举报已受理'}}</h2><p>请保存以下信息，查询凭证只在本次操作后显示。</p><label>受理编号<input :value="receiptResult.code" readonly></label><label>查询凭证<input :value="receiptResult.queryToken" readonly></label><p v-if="receiptResult.processing" class="warning-box">线索已保存，将进入人工研判队列。</p><button class="primary" @click="queryCode=receiptResult.code;queryToken=receiptResult.queryToken;receiptResult=null;user?refresh():go('lookup')">我已保存</button></section></div>
 <div v-if="toast" class="toast" role="status"><AppIcon name="check" :size="18"/>{{toast}}</div>
</template>
